<?php
declare(strict_types=1);
session_start();
require __DIR__ . '/config.php';
$_SESSION['csrf'] ??= bin2hex(random_bytes(24));
$error = '';
function admin_e(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function admin_csrf(): void { if (!hash_equals($_SESSION['csrf'] ?? '', (string)($_POST['csrf'] ?? ''))) { http_response_code(419); exit('Sessão expirada.'); } }
if (isset($_GET['logout'])) { session_destroy(); header('Location: admin.php'); exit; }
if (empty($_SESSION['admin_logged']) && $_SERVER['REQUEST_METHOD'] === 'POST') {
    admin_csrf();
    $stmt = $pdo->prepare('SELECT * FROM admin WHERE username = ?');
    $stmt->execute([trim((string)($_POST['username'] ?? ''))]); $admin = $stmt->fetch();
    if ($admin && password_verify((string)($_POST['password'] ?? ''), $admin['password'])) { session_regenerate_id(true); $_SESSION['admin_logged'] = true; header('Location: admin.php'); exit; }
    $error = 'Usuário ou senha inválidos.';
}
if (!empty($_SESSION['admin_logged']) && $_SERVER['REQUEST_METHOD'] === 'POST') {
    admin_csrf(); $action = (string)($_POST['action'] ?? ''); $id = (int)($_POST['id'] ?? 0);
    if ($action === 'toggle' && $id) $pdo->prepare("UPDATE tickets SET status=IF(status='active','inactive','active') WHERE id=?")->execute([$id]);
    elseif ($action === 'checkin' && $id) $pdo->prepare('UPDATE tickets SET checked_in=1,checkin_time=NOW() WHERE id=?')->execute([$id]);
    elseif ($action === 'add') {
        $name=trim((string)($_POST['nome']??'')); $email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL); $cpf=preg_replace('/\D/','',(string)($_POST['cpf']??''));
        if ($name && $email && strlen($cpf)===11) { $pdo->prepare("INSERT INTO tickets(hash,nome,email,cpf,payment_method) VALUES(?,?,?,?, 'manual')")->execute([bin2hex(random_bytes(24)),$name,$email,$cpf]); }
    }
    header('Location: admin.php?updated=1'); exit;
}
$tickets=[]; $stats=['total'=>0,'active'=>0,'checked'=>0];
if (!empty($_SESSION['admin_logged'])) { $tickets=$pdo->query('SELECT * FROM tickets ORDER BY id DESC')->fetchAll(); $stats['total']=count($tickets); foreach($tickets as $ticket){$stats['active']+=(int)($ticket['status']==='active');$stats['checked']+=(int)$ticket['checked_in'];} }
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel | Rota da Prosperidade</title><link rel="stylesheet" href="assets/style.css"></head>
<?php if (empty($_SESSION['admin_logged'])): ?><body class="system-page auth-page"><main class="auth-card"><img src="assets/logo.svg" alt="Rota da Prosperidade"><span class="system-kicker">Área restrita</span><h1>Bem-vindo de volta.</h1><p>Acesse a gestão da imersão.</p><?php if($error):?><div class="alert error"><?=admin_e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=admin_e($_SESSION['csrf'])?>"><label>Usuário<input name="username" required autocomplete="username"></label><label>Senha<input type="password" name="password" required autocomplete="current-password"></label><button class="primary-button" type="submit">Entrar no painel →</button></form></main></body>
<?php else: ?><body class="dashboard-page"><aside class="dashboard-sidebar"><img src="assets/logo.svg" alt="Rota da Prosperidade"><nav><a class="active" href="admin.php"><span>◫</span> Ingressos</a><a href="scanner.php"><span>⌗</span> Scanner</a><a href="index.php" target="_blank"><span>↗</span> Ver página</a></nav><a class="logout" href="?logout=1">Sair do painel</a></aside><main class="dashboard-main"><header><div><span class="system-kicker">Gestão do evento</span><h1>Ingressos</h1><p>Acompanhe inscrições e entradas em um só lugar.</p></div><button class="secondary-button" data-open-modal>+ Novo ingresso</button></header><?php if(isset($_GET['updated'])):?><div class="alert success">Alteração salva com sucesso.</div><?php endif?><section class="stats"><article><span>Total de inscrições</span><b><?=$stats['total']?></b></article><article><span>Ingressos ativos</span><b><?=$stats['active']?></b></article><article><span>Check-ins realizados</span><b><?=$stats['checked']?></b></article></section><section class="data-card"><div class="data-heading"><div><h2>Participantes</h2><p>Lista atualizada de ingressos emitidos.</p></div><input id="ticket-search" type="search" placeholder="Buscar participante ou CPF"></div><div class="table-wrap"><table><thead><tr><th>Participante</th><th>Pagamento</th><th>Status</th><th>Entrada</th><th>Ações</th></tr></thead><tbody><?php if(!$tickets):?><tr><td colspan="5" class="empty-state">Nenhum ingresso emitido ainda.</td></tr><?php endif?><?php foreach($tickets as $ticket):?><tr data-search="<?=admin_e(strtolower($ticket['nome'].' '.$ticket['cpf']))?>"><td><b><?=admin_e($ticket['nome'])?></b><small><?=admin_e($ticket['email'])?><br><?=admin_e($ticket['cpf'])?></small></td><td><?=admin_e(strtoupper($ticket['payment_method']))?></td><td><span class="status-badge <?=$ticket['status']==='active'?'active':'inactive'?>"><?=$ticket['status']==='active'?'Ativo':'Inativo'?></span></td><td><?=$ticket['checked_in']?'<b class="checked">✓ '.date('d/m H:i',strtotime($ticket['checkin_time'])).'</b>':'<span class="muted">Pendente</span>'?></td><td><div class="table-actions"><a href="ticket.php?hash=<?=admin_e($ticket['hash'])?>" target="_blank">Ver</a><form method="post"><input type="hidden" name="csrf" value="<?=admin_e($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=$ticket['id']?>"><?php if(!$ticket['checked_in']&&$ticket['status']==='active'):?><button name="action" value="checkin">Check-in</button><?php endif?><button class="danger-action" name="action" value="toggle"><?=$ticket['status']==='active'?'Inativar':'Ativar'?></button></form></div></td></tr><?php endforeach?></tbody></table></div></section></main><dialog id="ticket-modal"><form method="post" class="modal-form"><button type="button" class="modal-close" data-close-modal>×</button><span class="system-kicker">Cadastro manual</span><h2>Novo ingresso</h2><input type="hidden" name="csrf" value="<?=admin_e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="add"><label>Nome completo<input name="nome" required></label><label>E-mail<input name="email" type="email" required></label><label>CPF<input name="cpf" required maxlength="14"></label><button class="primary-button">Gerar ingresso →</button></form></dialog><script>const modal=document.querySelector('#ticket-modal');document.querySelector('[data-open-modal]').onclick=()=>modal.showModal();document.querySelector('[data-close-modal]').onclick=()=>modal.close();document.querySelector('#ticket-search').addEventListener('input',e=>document.querySelectorAll('tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(e.target.value.toLowerCase())));</script></body><?php endif?></html>
